import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Minimize diameter of a unit-separated 16-point triangular-lattice seed."""
    axial = np.array(
        [
            [0, -2], [1, -2],
            [-1, -1], [0, -1], [1, -1], [2, -1],
            [-2, 0], [-1, 0], [0, 0], [1, 0],
            [-2, 1], [-1, 1], [0, 1], [1, 1],
            [-2, 2], [-1, 2],
        ],
        dtype=np.float64,
    )
    seed = axial.copy()
    seed[:, 0] += 0.5 * seed[:, 1]
    seed[:, 1] *= 0.5 * np.sqrt(3.0)
    seed -= seed[0]

    pairs = np.triu_indices(16, 1)

    def unpack(z: np.ndarray) -> np.ndarray:
        return np.vstack((
            np.array([[0.0, 0.0], [1.0, 0.0]]),
            z[:-1].reshape(14, 2),
        ))

    def distances_squared(points: np.ndarray) -> np.ndarray:
        delta = points[pairs[0]] - points[pairs[1]]
        return np.einsum("ij,ij->i", delta, delta)

    def quality(points: np.ndarray) -> float:
        d2 = distances_squared(points)
        return float(d2.min() / d2.max())

    baseline = quality(seed)
    initial = np.concatenate((seed[2:].ravel(), [13.0]))

    try:
        from scipy.optimize import minimize

        # The final variable is an epigraph for all squared pair distances.
        # Thus minimizing it minimizes diameter after fixing d_min >= 1.
        def constraints(z: np.ndarray) -> np.ndarray:
            d2 = distances_squared(unpack(z))
            return np.concatenate((d2 - 1.0, z[-1] - d2))

        result = minimize(
            lambda z: z[-1],
            initial,
            method="SLSQP",
            constraints={"type": "ineq", "fun": constraints},
            options={"maxiter": 1500, "ftol": 1e-12, "disp": False},
        )
        candidate = unpack(result.x)
        if np.all(np.isfinite(candidate)) and quality(candidate) > baseline:
            return candidate
    except Exception:
        pass

    return seed


